/**
 * Song database on disk — the one place the song scripts read and write.
 *
 *   docs/songs.json        source of truth (id, title, artist, year, album, previewUrl, genre)
 *   docs/song-facts.json   "Wusstest du?" facts, { "<id>": "<fact>" }
 *   pwa/src/data/songs.ts  generated by sync-songs-ts.js — never written directly,
 *                          otherwise the facts would be dropped
 */
import fs from 'fs'
import path from 'path'
import { execFileSync } from 'child_process'
import { fileURLToPath } from 'url'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
export const ROOT = path.resolve(__dirname, '../../..')
export const SONGS_JSON = path.join(ROOT, 'docs/songs.json')
export const FACTS_JSON = path.join(ROOT, 'docs/song-facts.json')
export const AUDIO_DIR = path.join(ROOT, 'pwa/public/audio')
export const COVER_DIR = path.join(AUDIO_DIR, 'covers')
export const PUBLIC_AUDIO_URL = 'https://mxster.celox.io/audio'

export function loadSongs() {
  return JSON.parse(fs.readFileSync(SONGS_JSON, 'utf8'))
}

export function loadFacts() {
  return fs.existsSync(FACTS_JSON) ? JSON.parse(fs.readFileSync(FACTS_JSON, 'utf8')) : {}
}

/** Writes songs.json (+ facts) with a dated backup, then regenerates songs.ts. */
export function saveAll(songs, facts) {
  const stamp = new Date().toISOString().slice(0, 10)
  fs.copyFileSync(SONGS_JSON, `${SONGS_JSON}.backup-${stamp}`)
  fs.writeFileSync(SONGS_JSON, JSON.stringify(songs, null, 2) + '\n', 'utf8')
  if (facts) fs.writeFileSync(FACTS_JSON, JSON.stringify(sortById(facts), null, 2) + '\n', 'utf8')
  execFileSync(process.execPath, [path.join(ROOT, 'scripts/song-management/sync-songs-ts.js')], { stdio: 'inherit' })
}

function sortById(obj) {
  return Object.fromEntries(Object.entries(obj).sort(([a], [b]) => a.localeCompare(b)))
}

export function nextId(songs) {
  const max = songs.reduce((m, s) => Math.max(m, parseInt(s.id.replace('song_', ''), 10) || 0), -1)
  return `song_${String(max + 1).padStart(3, '0')}`
}

const norm = (s) =>
  s
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9]+/g, ' ')
    .trim()

/** Same song already in the database (artist + title, case and accents ignored). */
export function findDuplicate(songs, artist, title, exceptId) {
  return songs.find((s) => s.id !== exceptId && norm(s.artist) === norm(artist) && norm(s.title) === norm(title))
}

export function previewUrlFor(id) {
  return `${PUBLIC_AUDIO_URL}/${id}.mp3`
}
